function getSpeechRecognitionConstructor() {
  if (typeof window === 'undefined') {
    return null;
  }

  return (
    window.SpeechRecognition ||
    window.webkitSpeechRecognition ||
    null
  );
}

export function isSpeechRecognitionSupported() {
  return (
    typeof window !== 'undefined' &&
    ('SpeechRecognition' in window ||
      'webkitSpeechRecognition' in window)
  );
}

export function createRecognizer({
  lang = 'en-AU',
  interimResults = true,
  continuous = false,
} = {}) {
  if (!isSpeechRecognitionSupported()) {
    return null;
  }

  const SpeechRecognition =
    window.SpeechRecognition ||
    window.webkitSpeechRecognition;

  const recognizer = new SpeechRecognition();

  recognizer.lang = lang;
  recognizer.interimResults = interimResults;
  recognizer.continuous = continuous;
  recognizer.maxAlternatives = 1;

  return recognizer;
}

export function isSpeechSynthesisSupported() {
  return (
    typeof window !== 'undefined' &&
    'speechSynthesis' in window
  );
}

// --- Speech output --------------------------------------------------------

// Tunable "personality" for the assistant's voice. Rate is nudged above 1
// for a brisk, efficient corporate pace (not rushed); pitch is pulled back
// toward neutral (1.0) rather than the ~1.05 that reads a bit younger/
// chirpier — the combination is what gives the "professional agent" feel
// rather than a casual consumer-app voice.
export const VOICE_PROFILE = {
  lang: 'en-AU',
  rate: 1.08,
  pitch: 1.0,
  volume: 1,
};

let currentUtterance = null;
const cachedVoiceByLang = new Map();

// Browsers don't expose a gender flag on voices — only names. Voices are
// grouped into tiers so a genuinely good neural/natural voice always wins
// over a merely "female-sounding-name" legacy voice, instead of treating
// every hinted match as equal.
//
// Tier 3 (best): modern neural/natural TTS engines — these sound closest
//   to a real person and are what "corporate agent" voice product demos
//   actually use.
// Tier 2: named premium female voices commonly bundled with major OSes/
//   browsers that already sound clear and professional.
// Tier 1: generic female-hinted voices (fallback signal only).
const VOICE_TIERS = [
  {
    score: 3,
    patterns: ['neural', 'natural', 'online (natural)', 'premium'],
  },
  {
    score: 2,
    patterns: [
      'aria', 'jenny', 'sonia', 'emma', 'ava', 'michelle',
      'samantha', 'moira', 'tessa', 'karen',
      'google uk english female', 'google us english',
    ],
  },
  {
    score: 1,
    patterns: ['female', 'woman', 'zira', 'victoria', 'susan', 'linda', 'eva'],
  },
];

function scoreVoiceName(name) {
  const lower = name.toLowerCase();
  for (const tier of VOICE_TIERS) {
    if (tier.patterns.some((p) => lower.includes(p))) return tier.score;
  }
  return 0;
}

function pickFemaleVoice(voices, lang) {
  if (!voices || voices.length === 0) return null;

  const langPrefix = lang.split('-')[0].toLowerCase();

  // Prefer an exact locale match (e.g. en-AU) over a same-language-family
  // match (e.g. en-US) over anything else, so the accent stays consistent.
  const exactLocale = voices.filter((v) => v.lang?.toLowerCase() === lang.toLowerCase());
  const sameLanguage = voices.filter((v) => v.lang?.toLowerCase().startsWith(langPrefix));
  const pool = exactLocale.length ? exactLocale : sameLanguage.length ? sameLanguage : voices;

  const ranked = pool
    .map((voice) => ({ voice, score: scoreVoiceName(voice.name) }))
    .sort((a, b) => b.score - a.score);

  return ranked[0]?.voice || pool[0] || null;
}

// Some browsers (notably Chrome) return an empty voice list on the very
// first call — the real list only arrives via the 'voiceschanged' event.
function loadVoices() {
  return new Promise((resolve) => {
    const existing = window.speechSynthesis.getVoices();

    if (existing.length > 0) {
      resolve(existing);
      return;
    }

    window.speechSynthesis.onvoiceschanged = () => {
      resolve(window.speechSynthesis.getVoices());
    };

    // Fallback in case the event never fires on this browser.
    setTimeout(() => resolve(window.speechSynthesis.getVoices()), 500);
  });
}

export async function getPreferredVoice(lang = VOICE_PROFILE.lang) {
  if (cachedVoiceByLang.has(lang)) return cachedVoiceByLang.get(lang);
  const voices = await loadVoices();
  const voice = pickFemaleVoice(voices, lang);
  cachedVoiceByLang.set(lang, voice);
  return voice;
}

export function speak(
  text,
  {
    lang = VOICE_PROFILE.lang,
    rate = VOICE_PROFILE.rate,
    pitch = VOICE_PROFILE.pitch,
    volume = VOICE_PROFILE.volume,
    onStart,
    onEnd,
    onError,
  } = {}
) {
  if (!isSpeechSynthesisSupported() || !text) {
    onError?.('unsupported');
    return null;
  }

  window.speechSynthesis.cancel();

  const utterance = new SpeechSynthesisUtterance(text);
  utterance.lang = lang;
  utterance.rate = rate;
  utterance.pitch = pitch;
  utterance.volume = volume;

  const availableVoices = window.speechSynthesis.getVoices();

  if (availableVoices.length > 0) {
    if (!cachedVoiceByLang.has(lang)) {
      cachedVoiceByLang.set(lang, pickFemaleVoice(availableVoices, lang));
    }
    const voice = cachedVoiceByLang.get(lang);
    if (voice) utterance.voice = voice;
  } else {
    // Not loaded yet (common on the very first utterance in Chrome). This
    // one plays with the browser's default voice; kick off async loading
    // so every subsequent speak() call gets the right voice.
    loadVoices().then((voices) => {
      cachedVoiceByLang.set(lang, pickFemaleVoice(voices, lang));
    });
  }

  utterance.onstart = () => onStart?.();

  utterance.onend = () => {
    if (currentUtterance === utterance) currentUtterance = null;
    onEnd?.();
  };

  utterance.onerror = (event) => {
    if (currentUtterance === utterance) currentUtterance = null;
    if (event.error === 'interrupted' || event.error === 'canceled') {
      onEnd?.();
      return;
    }
    onError?.(event.error);
  };

  currentUtterance = utterance;
  window.speechSynthesis.speak(utterance);

  return utterance;
}

export function cancelSpeech() {
  if (!isSpeechSynthesisSupported()) return;
  window.speechSynthesis.cancel();
  currentUtterance = null;
}

export default {
  isSpeechRecognitionSupported,
  createRecognizer,
  isSpeechSynthesisSupported,
  speak,
  cancelSpeech,
  getPreferredVoice,
  VOICE_PROFILE,
};
